extern "C" s32 FJoyButtonPressed(JOY *joy, s32 mask) {
    s32 pressed = FJoyButtonPeek(joy, mask);
    ConsumeJoyButton(joy, mask);
    return pressed;
}

extern "C" s32 FJoyButtonPeek(JOY *joy, s32 mask) {
    return joy->grfbtnPressed & mask;
}

extern "C" void ConsumeJoyButton(JOY *joy, s32 mask) {
    joy->grfbtnPressed = joy->grfbtnPressed & ~mask;
    joy->grfbtnHeld = joy->grfbtnHeld | (joy->grfbtnLatest & mask);
}

extern "C" void func_00187E08(JOY *joy, s32 mask) {
    s32 inverse;

    inverse = ~mask;
    joy->grfbtnLatest = joy->grfbtnLatest & inverse;
    joy->grfbtnHeld = joy->grfbtnHeld & inverse;
}

